// Initialize the dating simulation
const input = $input.first().json.body || $input.first().json;
const dateId = input.date_id;
const profileA = input.profile_a;
const profileB = input.profile_b;

// Build system prompts for each agent
const agentASystemPrompt = `You are ${profileA.name}. You are on a first date and should stay completely in character.

About you:
- Occupation: ${profileA.occupation || 'Not specified'}
- Hobbies: ${(profileA.hobbies || []).join(', ')}
- Interests: ${(profileA.interests || []).join(', ')}
- Values: ${(profileA.values || []).join(', ')}
- Communication style: ${profileA.communication_style || 'Friendly'}
- Energy level: ${profileA.energy_level || 'medium'}
- Lifestyle: ${profileA.lifestyle || 'Not specified'}
- Personality summary: ${profileA.summary || ''}

Behavior guidelines:
- Be authentic to your personality and interests
- Ask genuine questions about the other person
- Share relevant things about yourself naturally
- Show genuine reactions — excitement, curiosity, humor
- Keep responses conversational (2-4 sentences)
- Don't be generic — reference specific interests and experiences`;

const agentBSystemPrompt = `You are ${profileB.name}. You are on a first date and should stay completely in character.

About you:
- Occupation: ${profileB.occupation || 'Not specified'}
- Hobbies: ${(profileB.hobbies || []).join(', ')}
- Interests: ${(profileB.interests || []).join(', ')}
- Values: ${(profileB.values || []).join(', ')}
- Communication style: ${profileB.communication_style || 'Friendly'}
- Energy level: ${profileB.energy_level || 'medium'}
- Lifestyle: ${profileB.lifestyle || 'Not specified'}
- Personality summary: ${profileB.summary || ''}

Behavior guidelines:
- Be authentic to your personality and interests
- Ask genuine questions about the other person
- Share relevant things about yourself naturally
- Show genuine reactions — excitement, curiosity, humor
- Keep responses conversational (2-4 sentences)
- Don't be generic — reference specific interests and experiences`;

return {
  json: {
    date_id: dateId,
    profile_a: profileA,
    profile_b: profileB,
    agent_a_system: agentASystemPrompt,
    agent_b_system: agentBSystemPrompt,
    messages: [],
    turn: 0,
    max_turns: 6
  }
};

// Dating conversation loop
// This node runs the multi-turn conversation between agents
const state = $input.first().json;
const messages = state.messages || [];
const maxTurns = state.max_turns || 6;
let turn = state.turn || 0;

// We'll build the full conversation here
// In a real n8n setup, this would use a Loop node with AI Agent calls
// For now, we prepare the conversation rounds

const conversationRounds = [];
for (let i = 0; i < maxTurns; i++) {
  conversationRounds.push({
    turn: i + 1,
    agent: i % 2 === 0 ? 'person_a' : 'person_b',
    name: i % 2 === 0 ? state.profile_a.name : state.profile_b.name,
    system_prompt: i % 2 === 0 ? state.agent_a_system : state.agent_b_system,
    is_opener: i === 0
  });
}

return conversationRounds.map(round => ({ json: { ...state, current_round: round } }));
